// Real disk drive recordings, 8 bit signed, 22 050 Hz, mono. Two sets so they can be compared by ear.
//
// VICE (src/drive/drive-sound.c, by Kajtar Zsolt; GNU GPL v2 or later; https://vice-emu.sourceforge.io): spin-up and spin-down of the
// motor, the looping hum, two head-step samples (inner tracks, outer tracks) and the bump against the stop.
//
// Ultimate (roms/sounds.bin of 1541ultimate by Gideon Zweijtzer; GNU GPL v3; https://github.com/GideonZ/1541ultimate): the looping
// motor hum, the sound of a disk slipping on the spindle, a step inwards, a step outwards and the head bang. The offsets are those
// of fpga/1541/vhdl_source/c1541_drive.vhd.
//
// Both are distributed with this program under the GNU General Public License v3, see LICENSE.
export type DriveSet = Record<string, string>;
export const VICE_SAMPLES: DriveSet = {
  hum: '',
  spinup: '',
  spindown: '',
  stepping: '',
  stepping2: '',
  bump: '',
};
export const ULTIMATE_SAMPLES: DriveSet = {
  hum: '',
  slip: '',
  in: '',
  out: '',
  bang: '',
};
